solution.javascript:
function moverCeros(nums) {
  let escribir = 0;
  for (let i = 0; i < nums.length; i++) {
    if (nums[i] !== 0) {
      [nums[escribir], nums[i]] = [nums[i], nums[escribir]];
      escribir++;
    }
  }
  return nums;
}

solution.python:
def moverCeros(nums):
    escribir = 0
    for i in range(len(nums)):
        if nums[i] != 0:
            nums[escribir], nums[i] = nums[i], nums[escribir]
            escribir += 1
    return nums
